/* JP6 pin 20: i.MX6ULL PWM3 hardware PWM consumer. */
#include <linux/module.h>
#include <linux/platform_device.h>
#include <linux/pwm.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <linux/math64.h>

/* Duty is expressed in 1/10000 of a period (one basis point). */
#define ALPHA_PWM_DUTY_SCALE 10000U

struct alpha_pwm {
	struct pwm_device *pwm;
	struct mutex lock;
	unsigned int frequency;
	unsigned int duty;
	bool enabled;
};

/* All runtime callers hold lock. Waveforms are generated by PWM3 hardware. */
static int alpha_pwm_apply(struct alpha_pwm *ap, unsigned int hz,
			   unsigned int duty, bool enabled)
{
	struct pwm_state state;
	int ret;

	pwm_init_state(ap->pwm, &state);
	state.period = div_u64(NSEC_PER_SEC, hz);
	state.duty_cycle = div_u64(state.period * duty, ALPHA_PWM_DUTY_SCALE);
	state.enabled = enabled;
	ret = pwm_apply_might_sleep(ap->pwm, &state);
	if (!ret) {
		ap->frequency = hz;
		ap->duty = duty;
		ap->enabled = enabled;
	}
	return ret;
}

static ssize_t pwm_show(struct device *dev, struct device_attribute *attr,
			char *buf)
{
	struct alpha_pwm *ap = dev_get_drvdata(dev);
	ssize_t ret;

	mutex_lock(&ap->lock);
	ret = sysfs_emit(buf, "%u %u %u\n", ap->frequency, ap->duty,
			 ap->enabled);
	mutex_unlock(&ap->lock);
	return ret;
}

static ssize_t pwm_store(struct device *dev, struct device_attribute *attr,
			 const char *buf, size_t count)
{
	struct alpha_pwm *ap = dev_get_drvdata(dev);
	char freq_buf[16], duty_buf[16], enable_buf[16], extra;
	unsigned int hz, duty, enabled;
	int ret;

	if (sscanf(buf, "%15s %15s %15s %c", freq_buf, duty_buf,
		   enable_buf, &extra) != 3 ||
	    kstrtouint(freq_buf, 10, &hz) ||
	    kstrtouint(duty_buf, 10, &duty) ||
	    kstrtouint(enable_buf, 10, &enabled) ||
	    hz < 1 || hz > 100000 || duty > ALPHA_PWM_DUTY_SCALE || enabled > 1)
		return -EINVAL;

	mutex_lock(&ap->lock);
	ret = alpha_pwm_apply(ap, hz, duty, enabled);
	mutex_unlock(&ap->lock);
	return ret ? ret : count;
}
static DEVICE_ATTR_RW(pwm);
static struct attribute *alpha_pwm_attrs[] = { &dev_attr_pwm.attr, NULL };
static const struct attribute_group alpha_pwm_group = {
	.attrs = alpha_pwm_attrs,
};

static void alpha_pwm_stop(void *data)
{
	struct alpha_pwm *ap = data;
	int ret;

	mutex_lock(&ap->lock);
	ret = alpha_pwm_apply(ap, ap->frequency, ap->duty, false);
	mutex_unlock(&ap->lock);
	if (ret)
		pr_warn("alpha-pwm: failed to disable PWM: %d\n", ret);
}

static int alpha_pwm_probe(struct platform_device *pdev)
{
	struct device *dev = &pdev->dev;
	struct alpha_pwm *ap;
	int ret;

	ap = devm_kzalloc(dev, sizeof(*ap), GFP_KERNEL);
	if (!ap)
		return -ENOMEM;
	mutex_init(&ap->lock);
	ap->pwm = devm_pwm_get(dev, NULL);
	if (IS_ERR(ap->pwm))
		return dev_err_probe(dev, PTR_ERR(ap->pwm), "cannot get PWM3\n");
	platform_set_drvdata(pdev, ap);
	ret = alpha_pwm_apply(ap, 1000, 5000, false);
	if (ret)
		return dev_err_probe(dev, ret, "cannot initialize PWM3\n");
	ret = devm_add_action_or_reset(dev, alpha_pwm_stop, ap);
	if (ret)
		return ret;
	/* devres removes sysfs before stopping and releasing the PWM. */
	return devm_device_add_group(dev, &alpha_pwm_group);
}

static void alpha_pwm_shutdown(struct platform_device *pdev)
{
	alpha_pwm_stop(platform_get_drvdata(pdev));
}

static const struct of_device_id alpha_pwm_of_match[] = {
	{ .compatible = "alientek,alpha-jp6-pwm" }, { }
};
MODULE_DEVICE_TABLE(of, alpha_pwm_of_match);
static struct platform_driver alpha_pwm_driver = {
	.probe = alpha_pwm_probe,
	.shutdown = alpha_pwm_shutdown,
	.driver = {
		.name = "alpha-jp6-pwm",
		.of_match_table = alpha_pwm_of_match,
	},
};
module_platform_driver(alpha_pwm_driver);
MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("ALIENTEK ALPHA JP6 pin20 hardware PWM control");
